/* Rime base element rules: reset, type, links, focus fallback, .sr-only,
   the bare-table look and the keyframes. Ships with tokens.css in the
   "base" registry item; import it after tokens.css. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  color-scheme: light;
}

body {
  margin: 0;
  min-height: 100dvh;
  background: var(--page-base);
  color: var(--ink-body);
  font-family: var(--font-body);
  font-size: var(--text-body);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

/* The bloom gradient lives on a fixed layer, not on body, so it stays pinned
   to the viewport as content scrolls. Glass needs something behind it to
   read as glass; over a flat field it is just a grey card. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  background: var(--page-background);
  pointer-events: none;
}

h1,
h2,
h3,
h4 {
  margin: 0;
  color: var(--ink-heading);
  line-height: 1.15;
}

h1,
h2 {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: var(--tracking-display);
}

h3,
h4 {
  font-family: var(--font-body);
  font-weight: 700;
  letter-spacing: -0.005em;
}

p {
  margin: 0;
}

a {
  color: var(--ink-brand);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

a:hover {
  color: var(--brand-deep);
}

button,
input,
select,
textarea {
  font: inherit;
  color: inherit;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: not-allowed;
}

img,
svg {
  display: block;
  max-width: 100%;
}

::selection {
  background: rgba(var(--rgb-brand), 0.22);
  color: var(--brand-deep);
}

/* Components draw their own focus with box-shadow. This is the fallback for
   anything that does not, so no focusable element is ever left unmarked. */
:focus-visible {
  outline: 2px solid var(--focus-color);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.tabular {
  font-variant-numeric: tabular-nums;
}

.mono {
  font-family: var(--font-mono);
  letter-spacing: 0.02em;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes fade-in {
  from {
    opacity: 0;
  }
}

/* The only overlay entrance: a short fade and 6px drop. No scale. */
@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(-6px);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Lists that carry a class are layout, not prose: drop the browser indent.
   Unclassed lists (legal copy, help text) keep their bullets. */
ul[class],
ol[class] {
  margin: 0;
  padding: 0;
  list-style: none;
}

/* Bare tables (styleguide specimens, prose) share the Table primitive's look. */
table:not([class]) {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--text-small);
}

thead:not([class]) th {
  padding: var(--table-head-pad);
  background: var(--table-head-fill);
  border-bottom: var(--table-head-rule);
  text-align: left;
  font-size: var(--text-caption);
  font-weight: 700;
  color: var(--table-head-ink);
}

tbody:not([class]) td,
tbody:not([class]) th {
  padding: var(--table-cell-pad);
  border-bottom: var(--table-row-line);
}

tbody:not([class]) tr:last-child td,
tbody:not([class]) tr:last-child th {
  border-bottom: 0;
}

/* shadcn variable names, aliased to Rime's tokens. One way only: edit the
   Rime tokens (or theme.css from Rime Studio), never these. They are var()
   references, so they follow the preset and the mode; they are declared on
