  --card: var(--surface-solid);
  --card-foreground: var(--ink-body);
  --popover: var(--popover-surface);
  --popover-foreground: var(--ink-body);
  --primary: var(--brand-action);
  --primary-foreground: var(--ink-inverse);
  --secondary: var(--surface-sunken);
  --secondary-foreground: var(--ink-heading);
  --muted: var(--surface-sunken);
  --muted-foreground: var(--ink-muted);
  --accent: var(--wash-hover);
  --accent-foreground: var(--ink-heading);
  --destructive: var(--danger-base-solid);
  --destructive-foreground: var(--ink-inverse);
  --border: var(--line);
  --input: var(--line-input);
  --ring: var(--focus-color);
  --radius: var(--r-md);
  --sidebar: var(--chrome-sidebar);
  --sidebar-foreground: var(--ink-secondary);
  --sidebar-primary: var(--brand-action);
  --sidebar-primary-foreground: var(--ink-inverse);
  --sidebar-accent: var(--wash-active);
  --sidebar-accent-foreground: var(--ink-heading);
  --sidebar-border: var(--line-soft);
  --sidebar-ring: var(--focus-color);
  --font-sans: var(--font-body);
