export { cx as cn };

import type { Ref, RefCallback } from "react";

/** Combines refs so a component can keep its own while honouring the caller's. */
export function mergeRefs<T>(...refs: Array<Ref<T> | undefined>): RefCallback<T> {
  return (value) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(value);
      else if (ref) (ref as { current: T | null }).current = value;
    }
  };
}

"use client";

import { useSyncExternalStore, type ReactNode } from "react";
import { createPortal } from "react-dom";

const subscribe = () => () => {};

/** True after hydration. The server snapshot is false, so portals never
    render during SSR and there is no hydration mismatch. */
export function useIsClient(): boolean {
  return useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
}

/**
 * Renders into document.body. Every popup goes through here: backdrop-filter
 * on a glass panel creates a containing block for position:fixed, so a
 * dropdown left inside the panel is clipped by it instead of the viewport.
 *
 * Portalled content leaves any data-theme scope. The presets still reach it
 * because tokens.css also matches :root:has([data-theme="flat"]) (and dark),
 * which lifts the preset onto <html> while a themed subtree is mounted. No
 * attribute copying is needed here.
 */
export function Portal({ children }: { children: ReactNode }) {
  const isClient = useIsClient();
  if (!isClient) return null;
  return createPortal(children, document.body);
}

/**
 * Places a fixed-position popup against its anchor, flipping above when there
 * is no room below. Writes straight to the element's style: position tracks
 * scroll and resize, and routing that through state would re-render on every
 * scroll frame.
 */
export function placePopup(
  anchor: HTMLElement,
  popup: HTMLElement,
  opts: { offset?: number; matchWidth?: boolean; align?: "start" | "end" | "center"; side?: "bottom" | "top" } = {},
): void {
  const { offset = 6, matchWidth = false, align = "start", side = "bottom" } = opts;
  const a = anchor.getBoundingClientRect();
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const margin = 8;

  if (matchWidth) popup.style.minWidth = `${a.width}px`;
  const p = popup.getBoundingClientRect();

  const roomBelow = vh - a.bottom - offset - margin;
  const roomAbove = a.top - offset - margin;
  const placeBelow = side === "bottom" ? roomBelow >= p.height || roomBelow >= roomAbove : roomAbove < p.height && roomBelow > roomAbove;

  let top = placeBelow ? a.bottom + offset : a.top - offset - p.height;
  top = Math.max(margin, Math.min(top, vh - p.height - margin));

  let left = align === "end" ? a.right - p.width : align === "center" ? a.left + a.width / 2 - p.width / 2 : a.left;
  left = Math.max(margin, Math.min(left, vw - p.width - margin));

  popup.style.top = `${Math.round(top)}px`;
  popup.style.left = `${Math.round(left)}px`;
  popup.dataset.placement = placeBelow ? "bottom" : "top";
}

/** Focusable descendants, in DOM order, for focus traps and roving focus. */
export function focusableWithin(root: HTMLElement): HTMLElement[] {
  const selector = [
    "a[href]",
    "button:not([disabled])",
    "input:not([disabled]):not([type=hidden])",
    "select:not([disabled])",
    "textarea:not([disabled])",
    "[tabindex]:not([tabindex='-1'])",
  ].join(",");
  return Array.from(root.querySelectorAll<HTMLElement>(selector)).filter(
    (el) => !el.hasAttribute("inert") && el.getAttribute("aria-hidden") !== "true" && el.offsetParent !== null,
  );
}

import { Children, cloneElement, isValidElement, type CSSProperties, type HTMLAttributes, type ReactElement, type ReactNode, type Ref } from "react";
import { cx } from "./cx";
import { mergeRefs } from "./merge-refs";

type AnyProps = Record<string, unknown> & {
  className?: string;
  style?: CSSProperties;
  ref?: Ref<unknown>;
};

export type SlotProps = HTMLAttributes<HTMLElement> & {
  children?: ReactNode;
  ref?: Ref<HTMLElement>;
};

/**
 * asChild support, as shadcn (Radix Slot) does it: renders its single child
 * element instead of its own tag, merging the props it was given onto it.
 * className joins (slot first, child after), style merges (child wins), and
 * event handlers both run (the child's first; the slot's is skipped when the
 * child's calls preventDefault). Refs are merged. Any other prop the child
 * sets wins over the slot's.
 */
export function Slot({ children, ref, ...slotProps }: SlotProps) {
  const child = Children.only(children);
  if (!isValidElement(child)) return null;
  const el = child as ReactElement<AnyProps>;
  const childProps = el.props;
  const merged: AnyProps = { ...(slotProps as AnyProps) };

  for (const key of Object.keys(childProps)) {
    const slotValue = (slotProps as AnyProps)[key];
    const childValue = childProps[key];
    if (/^on[A-Z]/.test(key) && typeof slotValue === "function" && typeof childValue === "function") {
      merged[key] = (...args: unknown[]) => {
        (childValue as (...a: unknown[]) => void)(...args);
        const event = args[0] as { defaultPrevented?: boolean } | undefined;
        if (!event?.defaultPrevented) (slotValue as (...a: unknown[]) => void)(...args);
      };
    } else if (key === "className") {
      merged.className = cx(slotProps.className, childProps.className);
    } else if (key === "style") {
      merged.style = { ...slotProps.style, ...childProps.style };
    } else if (key !== "children" && key !== "ref") {
      merged[key] = childValue;
    }
  }

  const childRef = childProps.ref;
  if (ref || childRef) merged.ref = mergeRefs(ref as Ref<unknown>, childRef as Ref<unknown>);
  return cloneElement(el, merged as Partial<AnyProps>);
}
